import React, { useState, useEffect } from 'react';
import { buildUrl } from '../utils/apiConfig';

const fieldRules = {
  name:            v => v.trim().length > 1,
  branchEmail1:    v => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()),
  branchPhone:     v => v.trim().length >= 7,
  countryID:       v => v !== '' && v !== '0' && v !== 0,
  provinceID:      v => v !== '' && v !== '0' && v !== 0,
  cityID:          v => v !== '' && v !== '0' && v !== 0,
  address:         v => v.trim().length > 5,
  academicSession: v => v.trim().length > 2,
  bankAccountno:   v => v.trim().length > 3,
  iban:            v => v.trim().length > 5,
};

const errorMsgs = {
  name:            'School name is required',
  branchEmail1:    'Enter a valid email address',
  branchPhone:     'Enter a valid phone number',
  countryID:       'Please select a country',
  provinceID:      'Please select a province',
  cityID:          'Please select a city',
  address:         'Please enter a complete address',
  academicSession: 'Please enter the academic session',
  bankAccountno:   'Account number is required',
  iban:            'IBAN is required',
};

function FormInput({ icon, id, type = 'text', placeholder, value, onChange, onBlur, fieldErrors }) {
  const status = fieldErrors[id];
  return (
    <div className="input-wrapper">
      {icon && <i className={`fas ${icon} input-icon`}></i>}
      <input
        className={`form-input${icon ? ' has-icon' : ''}${status === 'error' ? ' error-field' : status === 'ok' ? ' success-field' : ''}`}
        id={id}
        type={type}
        placeholder={placeholder}
        value={value ?? ''}
        onChange={e => onChange(id, e.target.value)}
        onBlur={e => onBlur && onBlur(id, e.target.value)}
      />
    </div>
  );
}

function FieldMsg({ id, fieldErrors }) {
  const status = fieldErrors[id];
  if (!status) return <span className="field-msg" />;
  if (status === 'ok')    return <span className="field-msg success"><i className="fas fa-check-circle"></i> Looks good</span>;
  if (status === 'error') return <span className="field-msg error"><i className="fas fa-times-circle"></i> {errorMsgs[id]}</span>;
  return <span className="field-msg" />;
}

export default function SchoolTab({ schoolInfo, setSchoolInfo, onSave, onSaveDraft, markUnsaved, showToast }) {
  const [fieldErrors, setFieldErrors]   = useState({});
  const [saving, setSaving]             = useState(false);
  const [countryList, setCountryList]   = useState([]);
  const [provinceList, setProvinceList] = useState([]);
  const [cityList, setCityList]         = useState([]);
  const [logoPreview, setLogoPreview]   = useState('');
  const [logoFile, setLogoFile]         = useState(null);

  /* ─── helpers ─────────────────────────────────────────── */
  const str  = v => (v ?? '').toString();
  const safe = field => schoolInfo?.[field] ?? '';

  const handleChange = (id, val) => {
    setSchoolInfo(prev => ({ ...prev, [id]: val }));
    markUnsaved?.();
    if (fieldRules[id]) {
      setFieldErrors(prev => ({ ...prev, [id]: fieldRules[id](str(val)) ? 'ok' : 'error' }));
    }
  };

  const handleBlur = (id, val) => {
    if (fieldRules[id]) {
      setFieldErrors(prev => ({
        ...prev,
        [id]: fieldRules[id](str(val)) ? 'ok' : (val ? 'error' : ''),
      }));
    }
  };

  const validateAll = () => {
    const required = ['name','branchEmail1','branchPhone','countryID','provinceID','cityID','address','academicSession'];
    const errors = {};
    const missing = [];
    required.forEach(id => {
      const val = str(schoolInfo?.[id] ?? '');
      const ok  = fieldRules[id] ? fieldRules[id](val) : val.trim().length > 0;
      errors[id] = ok ? 'ok' : 'error';
      if (!ok) missing.push(errorMsgs[id] || id);
    });
    setFieldErrors(prev => ({ ...prev, ...errors }));
    return missing;
  };

  /* ─── save ─────────────────────────────────────────────── */
  const handleSave = async () => {
    const missing = validateAll();
    if (missing.length) { onSave('error', missing); return; }
    setSaving(true);
    try {
      const UserID = sessionStorage.getItem('UserID') || 0;

      const formData = new FormData();

      formData.append('ID',                     schoolInfo.ID              ?? 0);
      formData.append('Name',                   schoolInfo.name            ?? '');
      formData.append('BranchCode',             schoolInfo.branchCode      ?? '');
      formData.append('Description',            schoolInfo.description     ?? '');
      formData.append('Address',                schoolInfo.address         ?? '');

      formData.append('CountryID',              schoolInfo.countryID       ?? 0);
      formData.append('ProvinceID',             schoolInfo.provinceID      ?? 0);
      formData.append('CityID',                 schoolInfo.cityID          ?? 0);

      formData.append('CreatedAt',              schoolInfo.createdAt       ?? new Date().toISOString());
      formData.append('CreatedBy',              schoolInfo.createdBy       ?? 0);
      formData.append('ModifiedAt',             new Date().toISOString());
      formData.append('ModifiedBy',             UserID);

      formData.append('IsActive',               schoolInfo.isActive        ?? true);

      formData.append('FineFee',                schoolInfo.fineFee         ?? 0);
      formData.append('FineEnabled',            schoolInfo.fineEnabled     ?? 0);

      formData.append('AcademicSession',        schoolInfo.academicSession ?? '');

      formData.append('BranchOwner',            schoolInfo.branchOwner     ?? '');
      formData.append('BranchEmail1',           schoolInfo.branchEmail1    ?? '');
      formData.append('BranchPhone',            schoolInfo.branchPhone     ?? '');

      formData.append('BankAccountno',          schoolInfo.bankAccountno   ?? '');
      formData.append('AccountDesc',            schoolInfo.accountDesc     ?? 0);

      formData.append('BranchLogo',             schoolInfo.branchLogo      ?? '');   // existing logo path

      formData.append('LaunchSetup',            schoolInfo.launchSetup     ?? 0);

      formData.append('IsManualRegNo',          schoolInfo.isManualRegNo        ?? true);
      formData.append('IsOperationalSOPs',      schoolInfo.isOperationalSOPs    ?? true);
      formData.append('IsFeeReceivingHeadWise', schoolInfo.isFeeReceivingHeadWise ?? true);
      formData.append('IsDiscChallan',          schoolInfo.isDiscChallan        ?? true);
      formData.append('IsTransportFee',         schoolInfo.isTransportFee       ?? true);
      formData.append('IsPLNeeded',             schoolInfo.isPLNeeded           ?? true);

      // file — only append when user picked a new logo
      if (logoFile) {
        formData.append('BranchLogoFile', logoFile);
      }

      const res  = await fetch(buildUrl('/api/Registration/update-branch'), {
        method: 'PUT',
        body:   formData,
      });
      const data = await res.json();

      setSaving(false);
      if (res.ok) {
        showToast('Branch updated successfully', 'success');
        onSave('success');
        getBranchdata();
      } else {
        showToast(data.message || 'Update failed', 'error');
      }
    } catch (err) {
      setSaving(false);
      showToast('Network error. Please try again.', 'error');
      console.error(err);
    }
  };

  const handleDraft = () => {
    setSaving(true);
    setTimeout(() => { setSaving(false); onSaveDraft(); }, 1000);
  };

  /* ─── data fetch ────────────────────────────────────────── */
  useEffect(() => {
    getCountryList();
    getBranchdata();
  }, []);

  useEffect(() => {
    if (schoolInfo?.countryID) getProvienceList(schoolInfo.countryID);
  }, [schoolInfo?.countryID]);

  useEffect(() => {
    if (schoolInfo?.provinceID) getCityList(schoolInfo.provinceID);
  }, [schoolInfo?.provinceID]);

  async function getCountryList() {
    try {
      const res  = await fetch(buildUrl('/api/Setting/get-countries'), { method: 'GET', headers: { Accept: '*/*' } });
      const json = await res.json();
      setCountryList(json.data ?? []);
    } catch (err) { showToast('Network error. Please try again.', 'error'); }
  }

  async function getProvienceList(countryId) {
    try {
      const res  = await fetch(buildUrl(`/api/Setting/get-provinces-by-country/${countryId}`), { method: 'GET', headers: { Accept: '*/*' } });
      const json = await res.json();
      setProvinceList(json.data ?? []);
    } catch (err) { showToast('Network error. Please try again.', 'error'); }
  }

  async function getCityList(provinceId) {
    try {
      const res  = await fetch(buildUrl(`/api/Setting/get-cities-by-province/${provinceId}`), { method: 'GET', headers: { Accept: '*/*' } });
      const json = await res.json();
      setCityList(json.data ?? []);
    } catch (err) { showToast('Network error. Please try again.', 'error'); }
  }

  async function getBranchdata() {
    try {
      const branchID = sessionStorage.getItem('branchID');
      const res      = await fetch(buildUrl(`/api/Registration/get-branch/${branchID}`), { method: 'GET', headers: { Accept: '*/*' } });
      const json     = await res.json();
      setSchoolInfo(json.data);
      setLogoPreview(json.data?.branchLogo || json.data?.logo || '');
      console.log(schoolInfo)
    } catch (err) { showToast('Network error. Please try again.', 'error'); }
  }

  /* ─── form-group wrapper ────────────────────────────────── */
  const FG = ({ label, id, required: req, children, helper }) => (
    <div className="form-group">
      <label className="form-label" htmlFor={id}>
        {label} {req && <span className="req-star">*</span>}
      </label>
      {children}
      <FieldMsg id={id} fieldErrors={fieldErrors} />
      {helper && <span className="form-helper info"><i className="fas fa-info-circle"></i> {helper}</span>}
    </div>
  );

  /* ─── render ────────────────────────────────────────────── */
  return (
    <div className="tab-panel active" id="panelSchool">

      {/* ── Basic Info ─────────────────────────────────────── */}
      <div className="section-card">
        <div className="section-header">
          <div className="section-icon blue"><i className="fas fa-info-circle"></i></div>
          <div>
            <div className="section-title">Basic School Information</div>
            <div className="section-desc">Core identity details for your school</div>
          </div>
        </div>

        <div className="form-grid form-grid-2" style={{ marginBottom: 16 }}>

          <FG label="School Name" id="name" required>
            <FormInput icon="fa-school" id="name" placeholder="e.g. Milford Sounds Academy"
              value={safe('name')} onChange={handleChange} onBlur={handleBlur} fieldErrors={fieldErrors} />
          </FG>

          <FG label="Branch Code" id="branchCode">
            <div className="input-wrapper">
              <i className="fas fa-id-card input-icon"></i>
              <input className="form-input has-icon" placeholder="e.g. 5790"
                value={safe('branchCode')}
                onChange={e => handleChange('branchCode', e.target.value)} />
            </div>
          </FG>

          <FG label="School Email" id="branchEmail1" required>
            <FormInput icon="fa-envelope" id="branchEmail1" type="email" placeholder="school@example.com"
              value={safe('branchEmail1')} onChange={handleChange} onBlur={handleBlur} fieldErrors={fieldErrors} />
          </FG>

          <FG label="Contact Number" id="branchPhone" required>
            <FormInput icon="fa-phone" id="branchPhone" type="tel" placeholder="+92 300 0000000"
              value={safe('branchPhone')} onChange={handleChange} onBlur={handleBlur} fieldErrors={fieldErrors} />
          </FG>

          <FG label="School Owner / Principal" id="branchOwner">
            <div className="input-wrapper">
              <i className="fas fa-user-tie input-icon"></i>
              <input className="form-input has-icon" placeholder="Full name"
                value={safe('branchOwner')}
                onChange={e => handleChange('branchOwner', e.target.value)} />
            </div>
          </FG>

          <FG label="Description" id="description">
            <div className="input-wrapper">
              <i className="fas fa-align-left input-icon"></i>
              <input className="form-input has-icon" placeholder="Short school description"
                value={safe('description')}
                onChange={e => handleChange('description', e.target.value)} />
            </div>
          </FG>

        </div>

        {/* Logo upload */}
        <div className="form-group">
          <label className="form-label">School Logo</label>
          <div className="upload-zone" onClick={() => document.getElementById('logoInput').click()}>
            {logoPreview ? (
              <img src={logoPreview} alt="School Logo"
                style={{ width: 120, height: 120, objectFit: 'cover', borderRadius: 10 }} />
            ) : (
              <>
                <div className="upload-icon"><i className="fas fa-image"></i></div>
                <div className="upload-title">Upload School Logo</div>
                <div className="upload-sub">Drag & drop or <span>click to browse</span> — JPG, PNG (max 2 MB)</div>
              </>
            )}
          </div>
          <input id="logoInput" type="file" accept="image/*" style={{ display: 'none' }}
            onChange={e => {
              const file = e.target.files[0];
              if (!file) return;
              setLogoFile(file);
              const reader = new FileReader();
              reader.onload = () => setLogoPreview(reader.result);
              reader.readAsDataURL(file);
            }} />
        </div>
      </div>

      {/* ── Location ───────────────────────────────────────── */}
      <div className="section-card">
        <div className="section-header">
          <div className="section-icon green"><i className="fas fa-map-marked-alt"></i></div>
          <div>
            <div className="section-title">Location Information</div>
            <div className="section-desc">Where your school is located</div>
          </div>
        </div>

        <div className="form-grid form-grid-3" style={{ marginBottom: 16 }}>

          <FG label="Country" id="countryID" required>
            <select
              className={`form-select${fieldErrors.countryID === 'error' ? ' error-field' : ''}`}
              value={safe('countryID')}
              onChange={e => {
                const val = e.target.value;
                handleChange('countryID',  val);
                handleChange('provinceID', '');
                handleChange('cityID',     '');
                setProvinceList([]);
                setCityList([]);
                if (val) getProvienceList(val);
              }}
            >
              <option value="">Select Country</option>
              {countryList.map(c => <option key={c.ID} value={c.ID}>{c.Name}</option>)}
            </select>
          </FG>

          <FG label="Province / State" id="provinceID" required>
            <select
              className={`form-select${fieldErrors.provinceID === 'error' ? ' error-field' : ''}`}
              value={safe('provinceID')}
              onChange={e => {
                const val = e.target.value;
                handleChange('provinceID', val);
                handleChange('cityID',     '');
                setCityList([]);
                if (val) getCityList(val);
              }}
            >
              <option value="">Select Province</option>
              {provinceList.map(p => <option key={p.ID} value={p.ID}>{p.Name}</option>)}
            </select>
          </FG>

          <FG label="City" id="cityID" required>
            <select
              className={`form-select${fieldErrors.cityID === 'error' ? ' error-field' : ''}`}
              value={safe('cityID')}
              onChange={e => handleChange('cityID', e.target.value)}
            >
              <option value="">Select City</option>
              {cityList.map(c => <option key={c.ID} value={c.ID}>{c.Name}</option>)}
            </select>
          </FG>

        </div>

        <FG label="Complete Address" id="address" required>
          <textarea
            className={`form-input${fieldErrors.address === 'error' ? ' error-field' : fieldErrors.address === 'ok' ? ' success-field' : ''}`}
            rows={2} placeholder="Street address, area, city..."
            value={safe('address')}
            onChange={e => handleChange('address', e.target.value)}
            onBlur={e => handleBlur('address', e.target.value)}
            style={{ resize: 'vertical', marginBottom: 0 }}
          />
        </FG>

        <div style={{ marginTop: 12 }}>
          <div className="form-grid form-grid-2">

            <FG label="Landmark" id="landmark">
              <input className="form-input" placeholder="Nearby landmark"
                value={safe('landmark')}
                onChange={e => handleChange('landmark', e.target.value)} />
            </FG>

            <FG label="Academic Session" id="academicSession" required>
              <input
                className={`form-input${fieldErrors.academicSession === 'error' ? ' error-field' : fieldErrors.academicSession === 'ok' ? ' success-field' : ''}`}
                placeholder="e.g. 2025-2026"
                value={safe('academicSession')}
                onChange={e => handleChange('academicSession', e.target.value)}
                onBlur={e => handleBlur('academicSession', e.target.value)}
              />
            </FG>

          </div>
        </div>
      </div>

      {/* ── Banking ────────────────────────────────────────── */}
      <div className="section-card">
        <div className="section-header">
          <div className="section-icon rose"><i className="fas fa-university"></i></div>
          <div>
            <div className="section-title">Banking & Fee Information</div>
            <div className="section-desc">Used on fee challans for parent payments</div>
          </div>
        </div>

        <div className="helper-banner">
          <i className="fas fa-info-circle"></i>
          <span>These banking details will be displayed to parents on fee challans and payment receipts. Please ensure all information is accurate.</span>
        </div>

        <div className="form-grid form-grid-2">

          <FG label="Bank Name" id="bankName">
            <div className="input-wrapper">
              <i className="fas fa-university input-icon"></i>
              <input className="form-input has-icon" placeholder="e.g. Bank Islami Pakistan"
                value={safe('bankName')}
                onChange={e => handleChange('bankName', e.target.value)} />
            </div>
          </FG>

          <FG label="Account Title" id="accountTitle">
            <div className="input-wrapper">
              <i className="fas fa-user input-icon"></i>
              <input className="form-input has-icon" placeholder="Account holder name"
                value={safe('accountTitle')}
                onChange={e => handleChange('accountTitle', e.target.value)} />
            </div>
          </FG>

          <FG label="Account Number" id="bankAccountno" required>
            <div className="input-wrapper">
              <i className="fas fa-hashtag input-icon"></i>
              <input
                className={`form-input has-icon${fieldErrors.bankAccountno === 'error' ? ' error-field' : fieldErrors.bankAccountno === 'ok' ? ' success-field' : ''}`}
                placeholder="Bank account number"
                value={safe('bankAccountno')}
                onChange={e => handleChange('bankAccountno', e.target.value)}
                onBlur={e => handleBlur('bankAccountno', e.target.value)}
              />
            </div>
          </FG>

          <FG label="IBAN" id="iban" required>
            <div className="input-wrapper">
              <i className="fas fa-credit-card input-icon"></i>
              <input
                className={`form-input has-icon${fieldErrors.iban === 'error' ? ' error-field' : fieldErrors.iban === 'ok' ? ' success-field' : ''}`}
                placeholder="PKXX BANK 0000 0000 0000"
                value={safe('iban')}
                onChange={e => handleChange('iban', e.target.value)}
                onBlur={e => handleBlur('iban', e.target.value)}
              />
            </div>
          </FG>

          <FG label="Branch Name" id="branchName">
            <div className="input-wrapper">
              <i className="fas fa-map-marker-alt input-icon"></i>
              <input className="form-input has-icon" placeholder="e.g. Blue Area Branch"
                value={safe('branchName')}
                onChange={e => handleChange('branchName', e.target.value)} />
            </div>
          </FG>

        </div>
      </div>

      {/* ── Save Bar ───────────────────────────────────────── */}
      <div className="save-bar">
        <div className="save-bar-left">
          <div className="autosave-dot"></div>
          <span>Draft auto-saved</span>
        </div>
        <div className="save-bar-right">
          <button className="btn btn-secondary btn-md" onClick={handleDraft} disabled={saving}>
            {saving
              ? <><i className="fas fa-spinner fa-spin"></i> Saving...</>
              : <><i className="fas fa-save"></i> Save Draft</>}
          </button>
          <button className="btn btn-primary btn-md" onClick={handleSave} disabled={saving}>
            {saving
              ? <><i className="fas fa-spinner fa-spin"></i> Saving...</>
              : <>Save & Continue <i className="fas fa-arrow-right"></i></>}
          </button>
        </div>
      </div>

    </div>
  );
}
